mapper.select:
SELECT id AS catId, name AS catName, cat_age AS age, cat_status AS catStatus, cat_img AS catImg, cat_info AS catInfo FROM pet
AND name LIKE CONCAT('%', #{inputName}, '%')
AND cat_age = #{inputAge}
AND cat_status = #{inputStatus}
AND cat_info LIKE CONCAT('%', #{inputCatInfo}, '%')
ORDER BY id ASC
